      "type": "scrutiny_notice",
      "quote": "Respondent No.1 issued Form GST ADT-01 proposing to conduct an audit under Section 65 of the CGST Act for the period from July, 2017 to March, 2022",
      "para": 9
    },
    {
      "date": "2023-12-20",
      "type": "reply_filed",
      "quote": "The Petitioner furnished documents and information in response to the said notice on 20.12.2023, 26.12.2023 and 13.01.2024",
      "para": 9
    },
    {
      "date": "2024-02-01",
      "type": "scn_issued",
      "quote": "an audit memo dated 01.02.2024 was issued raising various discrepancies relating, inter alia, to availment of input tax credit (ITC), payment of tax under Reverse Charge Mechanism (RCM) and other transactions",
      "para": 10
    },
    {
      "date": "2024-02-15",
      "type": "reply_filed",
      "quote": "The Petitioner submitted a Reply/Clarification dated 15.02.2024 along with supporting documents",
      "para": 10
    },
    {
      "date": "2024-03-26",
      "type": "scn_issued",
      "quote": "A further audit memo dated 26.03.2024 was issued raising, inter alia, allegations concerning ITC, RCM, supplies made to certain suppliers, export transactions and other issues",
      "para": 11
    },
    {
      "date": "2024-03-30",
      "type": "reply_filed",
      "quote": "The Petitioner submitted Replies dated 30.03.2024 and 26.04.2024 thereto",
      "para": 11
    },
    {
      "date": "2024-06-26",
      "type": "scn_issued",
      "quote": "Form GST ADT-02 under Section 65(6) of the CGST Act raising audit objections involving a tax liability of approximately Rs.78,53,548/-, excluding interest",
      "para": 12
    },
    {
      "date": "2024-07-08",
      "type": "pre_scn_intimation",
      "quote": "Form GST DRC-01A was issued intimating the proposed liability under Section 74(5) of the CGST Act",
      "para": 13
    },
    {
      "date": "2024-07-19",
      "type": "reply_filed",
      "quote": "The Petitioner submitted its response dated 19.07.2024, disputing both the audit findings as well as the proposed invocation of Section 74",
      "para": 13
    },
    {
      "date": "2024-07-26",
      "type": "scn_issued",
      "quote": "Respondent No.1 issued SCN in Form GST DRC-01 under Section 74(1) of the CGST Act proposing recovery of tax, interest and penalty",
      "para": 14
    },
    {
      "date": "2024-08-21",
      "type": "reply_filed",
      "quote": "The Petitioner had, vide communication dated 21.08.2024, informed the Department regarding the filing of the Writ Petition",
      "para": 15
    },
    {
      "date": "2025-02-03",
      "type": "order_passed",
      "quote": "the Impugned Order dated 03.02.2025, confirming the demand of tax, together with applicable interest and penalty, as determined therein",
      "para": 17
    }
  ],
  "document_contents": [
    {
      "type": "scn_ground",
      "quote": "the SCN alleges, inter alia, that the Petitioner had suppressed facts with intent to evade payment of appropriate taxes",
      "para": 14
    },
    {
      "type": "fraud_allegation",
      "quote": "the SCN alleges, inter alia, that the Petitioner had suppressed facts with intent to evade payment of appropriate taxes",
      "para": 14
    },
    {
      "type": "reply_point",
      "quote": "The Petitioner raised, inter alia, objections to the invocation of Section 74 of the CGST Act, the issuance of a consolidated SCN covering multiple financial years, the audit proceedings preceding the SCN and the individual demands proposed under the various heads",
      "para": 16
    },
    {
      "type": "order_reasoning",
      "quote": "the Impugned Order ... confirming the demand of tax, together with applicable interest and penalty, as determined therein",
      "para": 17
    }
  ]
}

